import Foundation
import MGDomain

/// The Model status page and Today's line (Mo 2026-10-11). What exists: `ModelCatalogue` (generated by
/// app/tools/gen_model_catalogue.py from the registry, ALGORITHM-REQUIREMENTS.md, ARCHITECTURE 8.1 and the code; it
/// also holds each row's stable number). What ran: today's rows (`s.metrics`, for today's blank reasons) and
/// `s.modelOutputs` (newest value per "metric|variant" over 60 days, imports included). Pure: no clock, no I/O.
///
/// States (Mo, 13:12): **has output** (own value, or past / imported data — said which) · **waiting for first night**
/// (only when no night has been recorded at all and the model needs one) · temporary: **not built yet — wave N**,
/// **blocked — needs X** (last). Anything else built without output is **not running** (a real failure, its reason
/// shown, as missing input / waiting for data / no value). Today's line counts model ids not running, and (apart) not built
/// or blocked.
public enum ModelStatusPresenter {
    /// Imported data variants: past data for every model of the same metric. "<id>:import" (a PC model run on imported
    /// history) counts only for that id's own row.
    static let dataImports: Set<String> = ["apple_health", "whoop_export", "apple"]
    /// Windows whose models need a recorded night.
    static let nightWindows: Set<String> = ["night", "morning", "14d", "28d"]
    /// ALG-051 needs last night's sleep too (its window is instant / day).
    static let nightNamed: Set<String> = ["alertness"]

    public static func make(_ s: PresenterSnapshot) -> ModelStatusState {
        let rows = allRows(s)
        func of(_ k: ModelStatusState.Row.Kind) -> [ModelStatusState.Row] {
            rows.filter { $0.kind == k }.sorted { $0.number < $1.number }
        }
        var sections: [ModelStatusState.Section] = []
        func add(_ id: String, _ title: String, _ note: String?, _ r: [ModelStatusState.Row]) {
            if !r.isEmpty { sections.append(ModelStatusState.Section(id: id, title: title, note: note, rows: r)) }
        }
        let notRunning = of(.notRunning)
        let has = of(.hasOutput)
        let night = of(.waitingFirstNight)
        let early = of(.tooEarly)
        let notBuilt = rows.filter { $0.kind == .notBuilt }.sorted {
            (wave($0), $0.number) < (wave($1), $1.number)
        }
        let blocked = of(.blocked)
        let byDesign = of(.byDesign)
        add("notRunning", "Not running", "Built, but no output: each row says why.", notRunning)
        add("tooEarly", "Too early today", "Needs 60 worn minutes today; fills in by itself.", early)
        add("hasOutput", "Has output", "A value today, or from past data (own or imported) — each row says where from.", has)
        add("waitingFirstNight", "Waiting for first night", "No night recorded yet; these start after the first one.",
            night)
        add("byDesign", "Not produced by this model, by design",
            "Listed in the catalogue, but the model never returns it; the model named in each row does.", byDesign)
        add("notBuilt", "Not built yet (temporary)", "Listed in ALGORITHM-REQUIREMENTS.md, no code yet; the wave is "
            + "the build queue in AUDIT-2026-10-11 §11.", notBuilt)
        add("blocked", "Blocked (temporary)", "Waiting for an input the app can't get yet.", blocked)
        let summary = "\(has.count) have output · \(night.count) waiting for first night · \(early.count) too early today"
            + " · \(notRunning.count) not running · \(notBuilt.count) not built yet · \(blocked.count) blocked"
        // Round 2 (2026-10-14, Mo's 9:11 AM screenshot "84 models not running"): the number counted not-built and blocked
        // models as "not running". Now each kind is counted by itself, so "not running" means built-but-silent only.
        let running = Set(notRunning.map(modelID))
        let unbuilt = Set((notBuilt + blocked).map(modelID)).subtracting(running)
        return ModelStatusState(sample: s.sample, summary: summary, sections: sections, notRunningModels: running.count,
                                notBuiltOrBlockedModels: unbuilt.count)
    }

    /// Today's line under the verdict: "3 models not running · 54 not built or blocked ›"; nil when every model has output
    /// or waits for a night. Each part is left out when its number is zero.
    public static func todayLine(_ s: PresenterSnapshot) -> ActionState? {
        let st = make(s)
        let n = st.notRunningModels, m = st.notBuiltOrBlockedModels
        var parts: [String] = []
        if n > 0 { parts.append("\(n) model\(n == 1 ? "" : "s") not running") }
        if m > 0 { parts.append("\(m) not built or blocked") }
        guard !parts.isEmpty else { return nil }
        return ActionState(id: "modelStatus", title: parts.joined(separator: " · ") + " ›", intent: .openModelStatus)
    }

    static func wave(_ r: ModelStatusState.Row) -> Int {
        Int(r.state.components(separatedBy: "wave ").last?.prefix { $0.isNumber } ?? "") ?? 99
    }

    /// The model id a row belongs to: the variant for a registry row, the ALG id for a requirement row.
    static func modelID(_ r: ModelStatusState.Row) -> String {
        String(r.id.split(separator: "|").last ?? Substring(r.id))
    }

    static func number(_ key: String) -> Int { ModelCatalogue.numbers[key] ?? 0 }

    static func allRows(_ s: PresenterSnapshot) -> [ModelStatusState.Row] {
        let reqs = Dictionary(ModelCatalogue.requirements.map { ($0.id, $0) }, uniquingKeysWith: { a, _ in a })
        let nightRecorded = ModelCatalogue.registry.contains { m in
            !nightWindows.isDisjoint(with: m.windows)
                && m.variants.contains { v in !v.hasSuffix(":import") && ownOutput(s, m.name, v) != nil }
        }
        var covered = Set<String>()
        var out: [ModelStatusState.Row] = []
        for m in ModelCatalogue.registry {
            for v in m.variants {
                let base = String(v.split(separator: ":").first ?? Substring(v))
                covered.insert(base)
                out.append(registryRow(s, m, variant: v, req: reqs[base], nightRecorded: nightRecorded))
            }
        }
        for r in ModelCatalogue.requirements where !covered.contains(r.id) {
            let key = "req|\(r.id)"
            let n = number(key)
            let title = "#\(n) · \(r.id) · \(r.what)"
            if let b = r.blockedOn {
                out.append(.init(id: key, number: n, title: title, state: "blocked — needs \(b)", detail: r.status,
                                 kind: .blocked, intent: nil))
            } else if r.codeProof == nil {
                out.append(.init(id: key, number: n, title: title, state: notBuiltState(r),
                                 detail: r.status.map { "ARCHITECTURE 8.1: \($0)" }, kind: .notBuilt, intent: nil))
            } else {
                out.append(.init(id: key, number: n, title: title, state: "has output · used inside the app (no metric of its own)",
                                 detail: r.codeProof, kind: .hasOutput, intent: nil))
            }
        }
        return out
    }

    static func notBuiltState(_ r: ModelCatalogue.Requirement) -> String {
        guard let w = r.wave else { return "not built yet" }
        return "not built yet — wave \(w)" + (r.waveIsDefault ? " (later-phase rows)" : "")
    }

    /// The model's own newest value: today's valued row, else the stored history.
    static func ownOutput(_ s: PresenterSnapshot, _ name: String, _ variant: String) -> ModelOutput? {
        if let m = s.metrics.first(where: { $0.name == name && $0.variant == variant && ($0.value?.isFinite ?? false) }) {
            return ModelOutput(value: m.value!, unit: m.unit, at: m.at, computedOnPC: m.computedOn == .pc,
                               importLabel: nil)
        }
        if let o = s.modelOutputs["\(name)|\(variant)"] { return o }
        // P9743 (2026-10-14): the PC writes LF / HF power under the variant "ALG-011" (hrv_rescore.py); "ALG-011:pc" is
        // registered too (WP-02, as requested) but nothing ever writes it, so its row said "not running" forever.
        // It is the same model, so its output is the "ALG-011" one.
        if let base = variantAlias["\(name)|\(variant)"] {
            return s.metrics.first { $0.name == name && $0.variant == base && ($0.value?.isFinite ?? false) }
                .map { ModelOutput(value: $0.value!, unit: $0.unit, at: $0.at, computedOnPC: $0.computedOn == .pc, importLabel: nil) }
                ?? s.modelOutputs["\(name)|\(base)"]
        }
        return nil
    }

    /// Registered variants that the PC writes under another variant id: "<metric>|<registered>" -> the variant it writes.
    static let variantAlias: [String: String] = ["hrv_lf|ALG-011:pc": "ALG-011", "hrv_hf|ALG-011:pc": "ALG-011"]

    /// T9852: "<metric>|<variant>" rows the variant's model never returns -> the model that does.
    static let notEmittedBy: [String: String] = ["ctl|MS-03": "ALG-036", "atl|MS-03": "ALG-036", "tsb|MS-03": "ALG-036"]

    static func registryRow(_ s: PresenterSnapshot, _ m: ModelCatalogue.RegistryMetric, variant v: String,
                            req: ModelCatalogue.Requirement?, nightRecorded: Bool) -> ModelStatusState.Row {
        let key = "\(m.name)|\(v)"
        let n = number(key)
        let title = "#\(n) · \(m.name) · \(v)"
        let open = UIIntent.openMetric(key: m.name, variant: v)
        // T9852: MS-03 (acl_ctl) returns only the ratio and band; CTL / ATL / TSB come from ALG-036. Label, never hide.
        if let giver = notEmittedBy[key] {
            return .init(id: key, number: n, title: title, state: "not produced by \(v) — \(giver) gives this",
                         detail: "The \(v) script returns only the acute:chronic ratio and its band.", kind: .byDesign,
                         intent: open)
        }
        let blankToday = s.metrics.first { $0.name == m.name && $0.variant == v && $0.value == nil }
        let todayNote = blankToday.map { "today: " + ($0.note ?? PresenterKit.noReason) }

        if let o = ownOutput(s, m.name, v) {
            let from = v.hasSuffix(":import") ? "computed on PC from imported history"
                : (o.computedOnPC ? "computed on the PC" : "from your own data")
            return .init(id: key, number: n, title: title, state: "\(outputValue(o, name: m.name)) · \(when(s, o.at)) · \(from)",
                         detail: todayNote, kind: .hasOutput, intent: open)
        }
        let base = String(v.split(separator: ":").first ?? Substring(v))
        let pastSources = m.importVariants.filter { dataImports.contains($0) || $0 == base + ":import" }
        let past = pastSources.compactMap { iv in s.modelOutputs["\(m.name)|\(iv)"].map { (iv, $0) } }
            .max { $0.1.at < $1.1.at }
        if let (iv, o) = past {
            let label = iv.hasSuffix(":import") ? "computed on PC from imported history"
                : (o.importLabel ?? ImportedHistory.memberLabel(iv) ?? iv)
            return .init(id: key, number: n, title: title,
                         state: "\(outputValue(o, name: m.name)) · from past data · \(label) · \(when(s, o.at))",
                         detail: todayNote ?? "this model's own value starts with your own data", kind: .hasOutput,
                         intent: open)
        }
        if let b = req?.blockedOn {
            return .init(id: key, number: n, title: title, state: "blocked — needs \(b)", detail: req?.status,
                         kind: .blocked, intent: open)
        }
        if let req, req.codeProof == nil {
            return .init(id: key, number: n, title: title, state: notBuiltState(req),
                         detail: req.status.map { "ARCHITECTURE 8.1: \($0)" }, kind: .notBuilt, intent: open)
        }
        if m.windows.contains("lab_draw") {
            return .init(id: key, number: n, title: title, state: "blocked — needs labs",
                         detail: "PhenoAge needs a complete lab draw in the Health vault (vault_dir on the PC)",
                         kind: .blocked, intent: open)
        }
        if let (have, need) = tooEarly(blankToday?.note) {
            return .init(id: key, number: n, title: title, state: "too early today — \(have) of \(need) worn minutes",
                         detail: todayNote, kind: .tooEarly, intent: open)
        }
        let needsNight = !nightWindows.isDisjoint(with: m.windows) || nightNamed.contains(m.name)
        if needsNight && !nightRecorded {
            return .init(id: key, number: n, title: title, state: "waiting for first night",
                         detail: "no night recorded yet", kind: .waitingFirstNight, intent: open)
        }
        return .init(id: key, number: n, title: title, state: "not running — " + why(m, blankToday),
                     detail: fix(m, blankToday), kind: .notRunning, intent: open)
    }

    static func outputValue(_ output: ModelOutput, name: String) -> String {
        let (text, unit) = MetricText.format(output.value, unit: output.unit, name: name)
        let value = unit.map { "\(text) \($0)" } ?? text
        let raw = MetricText.rawNames.contains(name) || output.unit.hasPrefix("raw_") || output.unit == "ticks"
        return raw ? "\(value) · decoded, untested" : value
    }

    /// T92: the two day blanks that mean "not enough worn minutes yet" (ScriptMembers MS-01 / MS-02: "no strap data
    /// this day (5 worn min, needs 60)"; ALG-036: "needs 60 worn waking minutes (have 5)"). Only while fewer than
    /// needed; the numbers come from the model's own note.
    static func tooEarly(_ note: String?) -> (have: Int, need: Int)? {
        guard let note else { return nil }
        let patterns = [#"no strap data this day \((\d+) worn min, needs (\d+)\)"#,
                        #"needs (\d+) worn waking minutes \(have (\d+)\)"#]
        for (i, p) in patterns.enumerated() {
            guard let re = try? NSRegularExpression(pattern: p),
                  let m = re.firstMatch(in: note, range: NSRange(note.startIndex..., in: note)),
                  let a = Range(m.range(at: 1), in: note).flatMap({ Int(note[$0]) }),
                  let b = Range(m.range(at: 2), in: note).flatMap({ Int(note[$0]) }) else { continue }
            let (have, need) = i == 0 ? (a, b) : (b, a)
            return have < need ? (have, need) : nil
        }
        return nil
    }

    /// Round 2: every not-running row names its kind first, so the list answers "why" per model: **missing input** (an input
    /// the model needs is absent or unusable: the model's own note, or no test / workout yet), **waiting for data**
    /// (nothing has reached the phone from the model's window or from the PC yet), or **no value** (it ran and said no).
    /// Not-built and blocked models are other states (their rows say "not built yet — wave N", "blocked — needs X").
    static func why(_ m: ModelCatalogue.RegistryMetric, _ blank: Metric?) -> String {
        let reason = whyNot(m, blank)
        if let note = blank?.note, !note.isEmpty {
            let l = note.lowercased()
            let missing = ["needs", "no ", "not enough", "missing", "too few", "fewer", "without", "empty", "not set"]
                .contains { l.hasPrefix($0) || l.contains($0) }
            return (missing ? "missing input: " : "no value: ") + reason
        }
        if m.windows.contains("test") || m.windows.allSatisfy({ $0 == "workout" }) { return "missing input: " + reason }
        return "waiting for data: " + reason
    }

    static func whyNot(_ m: ModelCatalogue.RegistryMetric, _ blank: Metric?) -> String {
        if let note = blank?.note { return note }
        if m.windows.contains("test") { return "no reaction test yet (Log › Sleepy & check-in › Reaction test)" }
        if m.windows.allSatisfy({ $0 == "workout" }) { return "no workout recorded yet" }
        if m.computedOnPC { return "computed on the PC: nothing has arrived from it yet" }
        return "nothing stored in the last 60 days"
    }

    static func fix(_ m: ModelCatalogue.RegistryMetric, _ blank: Metric?) -> String {
        let reason = blank?.note?.lowercased() ?? ""
        if reason.contains("noisy") { return "Fix: adjust the strap fit, then record the next window." }
        if m.windows.contains("test") { return "Fix: take the reaction test." }
        if m.windows.allSatisfy({ $0 == "workout" }) { return "Fix: record a workout." }
        if m.computedOnPC || reason.contains("pc") { return "Fix: run the model on the PC, then sync its result." }
        return "Fix: record the model's next window, then sync again."
    }

    static func when(_ s: PresenterSnapshot, _ at: Date) -> String {
        s.calendar.isDate(at, inSameDayAs: s.now) ? s.hm(at) : MGFormat.shortDate(at, calendar: s.calendar)
    }
}
